//! EGM96 against two other implementations over 2020 points: GeographicLib's
//! `GeoidEval` on the same grid (printed to 0.1 mm), and PROJ on NGA's
//! unquantised grid. Generated by `tools/reference.py`.

#![cfg(feature = "egm96")]
#![allow(clippy::expect_used)]

use kinavis_geoid::{GridGeoid, Interpolation};
use kinavis_kernel::geodesy::GeoidModel;
use kinavis_kernel::Position;

const REFERENCE: &str = include_str!("data/egm96_reference.txt");

/// (latitude, longitude, PROJ bilinear, GeographicLib bilinear, GeographicLib
/// cubic).
fn points() -> impl Iterator<Item = [f64; 5]> {
    REFERENCE
        .lines()
        .filter(|line| !line.starts_with('#'))
        .map(|line| {
            let mut fields = line
                .split_ascii_whitespace()
                .map(|field| field.parse::<f64>().expect("a number"));
            core::array::from_fn(|_| fields.next().expect("five columns"))
        })
}

fn height(geoid: &GridGeoid<'_>, latitude: f64, longitude: f64) -> f64 {
    geoid
        .undulation(Position::from_degrees(latitude, longitude).expect("on Earth"))
        .expect("a global grid")
        .metres()
}

#[test]
fn the_interpolation_is_geographiclibs_to_its_printed_digits() {
    let cubic = GridGeoid::EGM96;
    let bilinear = GridGeoid::EGM96.with_interpolation(Interpolation::Bilinear);
    let mut checked = 0;
    for [latitude, longitude, _, by_bilinear, by_cubic] in points() {
        let ours = height(&bilinear, latitude, longitude);
        assert!(
            (ours - by_bilinear).abs() <= 5.1e-5,
            "bilinear at {latitude} {longitude}: {ours} against {by_bilinear}"
        );
        let ours = height(&cubic, latitude, longitude);
        assert!(
            (ours - by_cubic).abs() <= 5.1e-5,
            "cubic at {latitude} {longitude}: {ours} against {by_cubic}"
        );
        checked += 1;
    }
    assert_eq!(checked, 2020);
}

#[test]
fn the_grid_is_ngas_to_its_storage_step() {
    // 3 mm steps: half a step of rounding, plus PROJ's float32.
    let bilinear = GridGeoid::EGM96.with_interpolation(Interpolation::Bilinear);
    for [latitude, longitude, by_proj, _, _] in points() {
        let ours = height(&bilinear, latitude, longitude);
        assert!(
            (ours - by_proj).abs() < 2e-3,
            "at {latitude} {longitude}: {ours} against PROJ {by_proj}"
        );
    }
}

#[test]
fn the_embedded_grid_reads_back_through_the_parser() {
    let parsed = GridGeoid::from_pgm(include_bytes!("../data/egm96-15.pgm")).expect("valid");
    assert_eq!(parsed, GridGeoid::EGM96);
    assert_eq!(parsed.dimensions(), (1440, 721));
}
